const item = $input.first().json;

const raw = item.text 
  ?? item.response?.generations?.[0]?.[0]?.text 
  ?? item.output 
  ?? item.response;

if (!raw) {
  throw new Error('Could not find response text. Available fields: ' + Object.keys(item).join(', '));
}

const cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();
const tickets = JSON.parse(cleaned);

return tickets.map(t => ({ json: { ticket_text: t } }));
